package com.scalix.workload;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.SplittableRandom;

/**
 * Generates the request sequence for a {@link WorkloadSpec}.
 *
 * <p>Arrivals follow a (possibly non-homogeneous) Poisson process generated by Lewis–Shedler
 * thinning: candidate arrivals are drawn at the maximum rate and each is kept with probability
 * {@code rate(t) / maxRate}. Request lengths are uniform around the configured mean. A single
 * seeded {@link SplittableRandom} drives everything, so the output is fully reproducible.
 */
public final class WorkloadGenerator {

    private WorkloadGenerator() { }

    public static List<Request> generate(WorkloadSpec spec) {
        final SplittableRandom rnd = new SplittableRandom(spec.seed());
        final double lambdaMax = spec.maxRate();
        final double minLen = spec.meanLengthMi() * (1 - spec.lengthVariation());
        final double maxLen = spec.meanLengthMi() * (1 + spec.lengthVariation());

        final List<Request> out = new ArrayList<>((int) Math.min(Integer.MAX_VALUE, spec.expectedRequests() * 1.2 + 16));
        double t = 0;
        long id = 0;
        while (true) {
            // Exponential inter-arrival at lambdaMax; 1 - nextDouble() is in (0, 1], so log is finite.
            t += -Math.log(1.0 - rnd.nextDouble()) / lambdaMax;
            if (t >= spec.durationSeconds()) {
                break;
            }
            final double accept = rnd.nextDouble();
            // Always draw the length so the random stream does not depend on acceptance branches
            // in ways that make small rate changes reshuffle every later request.
            final double u = rnd.nextDouble();
            if (accept * lambdaMax < spec.rateAt(t)) {
                final long length = Math.max(1, Math.round(minLen + u * (maxLen - minLen)));
                out.add(new Request(id++, t, length, spec.requestPes()));
            }
        }
        return Collections.unmodifiableList(out);
    }
}
